// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetConfig What the web app needs before anyone signs in
	// (GET /api/config)
	GetConfig(ctx context.Context, request GetConfigRequestObject) (GetConfigResponseObject, error)
	// GetCustomer The customer of the active organization and its Kafka cluster
	// (GET /api/customer)
	GetCustomer(ctx context.Context, request GetCustomerRequestObject) (GetCustomerResponseObject, error)
	// GetAlertSettings The thresholds of the customer's alerts, and which receivers are set
	// (GET /api/customer/alert-settings)
	GetAlertSettings(ctx context.Context, request GetAlertSettingsRequestObject) (GetAlertSettingsResponseObject, error)
	// ChangeAlertSettings Changes the thresholds of the customer's alerts; for organization admins
	// (PUT /api/customer/alert-settings)
	ChangeAlertSettings(ctx context.Context, request ChangeAlertSettingsRequestObject) (ChangeAlertSettingsResponseObject, error)
	// RemoveAlertReceiver Stops sending the customer's alerts to a receiver; for organization admins
	// (DELETE /api/customer/alert-settings/receivers/{receiver})
	RemoveAlertReceiver(ctx context.Context, request RemoveAlertReceiverRequestObject) (RemoveAlertReceiverResponseObject, error)
	// SetAlertReceiver Sends the customer's alerts to a Slack webhook, a PagerDuty integration or a webhook too; for organization admins
	// (PUT /api/customer/alert-settings/receivers/{receiver})
	SetAlertReceiver(ctx context.Context, request SetAlertReceiverRequestObject) (SetAlertReceiverResponseObject, error)
	// ListAlerts The active alerts about the customer's own applications (docs/alerts.md)
	// (GET /api/customer/alerts)
	ListAlerts(ctx context.Context, request ListAlertsRequestObject) (ListAlertsResponseObject, error)
	// StreamAlerts The active alerts about the customer's own applications, as server-sent events: an alerts event with the AlertList at once and whenever it changes. The stream ends when the session token expires; open it again with a new one.
	// (GET /api/customer/alerts/stream)
	StreamAlerts(ctx context.Context, request StreamAlertsRequestObject) (StreamAlertsResponseObject, error)
	// GetClientProperties A client.properties with the admin user's credentials, for organization admins
	// (GET /api/customer/client-properties)
	GetClientProperties(ctx context.Context, request GetClientPropertiesRequestObject) (GetClientPropertiesResponseObject, error)
	// GetConnection How the customer's clients connect, without the password
	// (GET /api/customer/connection)
	GetConnection(ctx context.Context, request GetConnectionRequestObject) (GetConnectionResponseObject, error)
	// ListConsumerGroups The consumer groups' lag per topic, with the last hour of it
	// (GET /api/customer/consumer-groups)
	ListConsumerGroups(ctx context.Context, request ListConsumerGroupsRequestObject) (ListConsumerGroupsResponseObject, error)
	// GetConsumerGroupLag How far behind a consumer group was on each topic it reads, over a range
	// (GET /api/customer/consumer-groups/{group}/lag)
	GetConsumerGroupLag(ctx context.Context, request GetConsumerGroupLagRequestObject) (GetConsumerGroupLagResponseObject, error)
	// ListEvents The changes in the cluster over a range, for the timeline over the graphs (docs/timeline.md): all of them, or those about a topic, or about a consumer group and the topics it reads. Broker restarts show in each.
	// (GET /api/customer/events)
	ListEvents(ctx context.Context, request ListEventsRequestObject) (ListEventsResponseObject, error)
	// GetHealth The brokers and the partitions' health
	// (GET /api/customer/health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetSourceOptions What a new Postgres CDC source may be, and where Changeport connects from
	// (GET /api/customer/source-options)
	GetSourceOptions(ctx context.Context, request GetSourceOptionsRequestObject) (GetSourceOptionsResponseObject, error)
	// ListSources The customer's Postgres CDC sources
	// (GET /api/customer/sources)
	ListSources(ctx context.Context, request ListSourcesRequestObject) (ListSourcesResponseObject, error)
	// CreateSource Creates a source once its database passes the checks, for organization admins
	// (POST /api/customer/sources)
	CreateSource(ctx context.Context, request CreateSourceRequestObject) (CreateSourceResponseObject, error)
	// CheckSource Checks a database for a source, as Changeport will connect to it, for organization admins
	// (POST /api/customer/sources/checks)
	CheckSource(ctx context.Context, request CheckSourceRequestObject) (CheckSourceResponseObject, error)
	// GetSetupSQL The SQL and steps that set a database up for a new source, for organization admins
	// (POST /api/customer/sources/setup-sql)
	GetSetupSQL(ctx context.Context, request GetSetupSQLRequestObject) (GetSetupSQLResponseObject, error)
	// ListSourceTables The tables of a database a source may sync, for organization admins
	// (POST /api/customer/sources/tables)
	ListSourceTables(ctx context.Context, request ListSourceTablesRequestObject) (ListSourceTablesResponseObject, error)
	// DeleteSource Deletes a source, which drops its slot; for organization admins
	// (DELETE /api/customer/sources/{source})
	DeleteSource(ctx context.Context, request DeleteSourceRequestObject) (DeleteSourceResponseObject, error)
	// GetSource A source, with each table's progress and its slot's health
	// (GET /api/customer/sources/{source})
	GetSource(ctx context.Context, request GetSourceRequestObject) (GetSourceResponseObject, error)
	// ChangeSource Changes a source's tables, retention or state, for organization admins
	// (PATCH /api/customer/sources/{source})
	ChangeSource(ctx context.Context, request ChangeSourceRequestObject) (ChangeSourceResponseObject, error)
	// GetSourceCatalog The tables of an existing source's database, as the source controller last listed them for the table picker; for organization admins
	// (GET /api/customer/sources/{source}/catalog)
	GetSourceCatalog(ctx context.Context, request GetSourceCatalogRequestObject) (GetSourceCatalogResponseObject, error)
	// RequestSourceCatalog Asks the source controller to list the tables of an existing source's database, which the console cannot log in to; for organization admins
	// (POST /api/customer/sources/{source}/catalog)
	RequestSourceCatalog(ctx context.Context, request RequestSourceCatalogRequestObject) (RequestSourceCatalogResponseObject, error)
	// SetSourcePassword Gives a source the role's new password, once it logs in; for organization admins
	// (PUT /api/customer/sources/{source}/password)
	SetSourcePassword(ctx context.Context, request SetSourcePasswordRequestObject) (SetSourcePasswordResponseObject, error)
	// ConfirmSlotDropped Confirms that the customer dropped a deleted source's slot themselves; for organization admins
	// (POST /api/customer/sources/{source}/slot-dropped)
	ConfirmSlotDropped(ctx context.Context, request ConfirmSlotDroppedRequestObject) (ConfirmSlotDroppedResponseObject, error)
	// GetSourceSQL The SQL for a change to a source's database, for organization admins
	// (POST /api/customer/sources/{source}/sql)
	GetSourceSQL(ctx context.Context, request GetSourceSQLRequestObject) (GetSourceSQLResponseObject, error)
	// GetThroughput Bytes in and out per second over the whole cluster, or one topic
	// (GET /api/customer/throughput)
	GetThroughput(ctx context.Context, request GetThroughputRequestObject) (GetThroughputResponseObject, error)
	// GetTopicPolicy The guardrails on the customer's topics, for the create dialog
	// (GET /api/customer/topic-policy)
	GetTopicPolicy(ctx context.Context, request GetTopicPolicyRequestObject) (GetTopicPolicyResponseObject, error)
	// ListTopics The customer's topics, with their settings, size and throughput
	// (GET /api/customer/topics)
	ListTopics(ctx context.Context, request ListTopicsRequestObject) (ListTopicsResponseObject, error)
	// CreateTopic Creates a topic within the guardrails, for organization admins
	// (POST /api/customer/topics)
	CreateTopic(ctx context.Context, request CreateTopicRequestObject) (CreateTopicResponseObject, error)
	// DeleteTopic Deletes a topic and its messages, for organization admins
	// (DELETE /api/customer/topics/{topic})
	DeleteTopic(ctx context.Context, request DeleteTopicRequestObject) (DeleteTopicResponseObject, error)
	// ListTopicConsumerGroups The consumer groups with committed offsets on a topic
	// (GET /api/customer/topics/{topic}/consumer-groups)
	ListTopicConsumerGroups(ctx context.Context, request ListTopicConsumerGroupsRequestObject) (ListTopicConsumerGroupsResponseObject, error)
	// TailTopic The topic's recent messages and then new ones as they arrive, as server-sent events, for organization admins: a message event with a TailMessage per message, and a skipped event with a TailSkipped when more arrive than the stream shows. Each tail is audited; no message is kept. The stream ends when the session token expires; open it again with resume, to go on where it ended.
	// (GET /api/customer/topics/{topic}/tail)
	TailTopic(ctx context.Context, request TailTopicRequestObject) (TailTopicResponseObject, error)
	// GetTopology How data flows through the cluster now, for the topology map: the producers, topics and consumer groups, and the bytes per second between them over the last 5 minutes, with each group's lag
	// (GET /api/customer/topology)
	GetTopology(ctx context.Context, request GetTopologyRequestObject) (GetTopologyResponseObject, error)
	// GetMe Who is signed in, and what they may see
	// (GET /api/me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// ListCustomers Every customer, for operators
	// (GET /api/operator/customers)
	ListCustomers(ctx context.Context, request ListCustomersRequestObject) (ListCustomersResponseObject, error)
	// ProvisionCustomer Provision a customer, for operators
	// (POST /api/operator/customers)
	ProvisionCustomer(ctx context.Context, request ProvisionCustomerRequestObject) (ProvisionCustomerResponseObject, error)
	// DeprovisionCustomer Deprovision a customer, for operators
	// (DELETE /api/operator/customers/{customerID})
	DeprovisionCustomer(ctx context.Context, request DeprovisionCustomerRequestObject) (DeprovisionCustomerResponseObject, error)
	// GetOperatorCustomer One customer, for operators
	// (GET /api/operator/customers/{customerID})
	GetOperatorCustomer(ctx context.Context, request GetOperatorCustomerRequestObject) (GetOperatorCustomerResponseObject, error)
	// ListTrialRequests Every trial request, newest first, for operators
	// (GET /api/operator/trial-requests)
	ListTrialRequests(ctx context.Context, request ListTrialRequestsRequestObject) (ListTrialRequestsResponseObject, error)
	// ApproveTrialRequest Approve a pending trial request, for operators
	// (POST /api/operator/trial-requests/{trialRequestID}/approve)
	ApproveTrialRequest(ctx context.Context, request ApproveTrialRequestRequestObject) (ApproveTrialRequestResponseObject, error)
	// DeclineTrialRequest Decline a pending trial request, for operators
	// (POST /api/operator/trial-requests/{trialRequestID}/decline)
	DeclineTrialRequest(ctx context.Context, request DeclineTrialRequestRequestObject) (DeclineTrialRequestResponseObject, error)
	// RequestTrial Request a trial
	// (POST /api/trial-requests)
	RequestTrial(ctx context.Context, request RequestTrialRequestObject) (RequestTrialResponseObject, error)
	// ListMyTrialRequests The signed-in user's trial requests, newest first
	// (GET /api/trial-requests/mine)
	ListMyTrialRequests(ctx context.Context, request ListMyTrialRequestsRequestObject) (ListMyTrialRequestsResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetConfig operation middleware
func (sh *strictHandler) GetConfig(w http.ResponseWriter, r *http.Request) {
	var request GetConfigRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.GetConfig(ctx, request.(GetConfigRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetConfig")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(GetConfigResponseObject); ok {
		if err := validResponse.VisitGetConfigResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

